//go:build ignore

#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>

struct {
    __uint(type, BPF_MAP_TYPE_REUSEPORT_SOCKARRAY);
    __uint(max_entries, 128);
    __type(key, __u32);
    __type(value, __u32);
    __uint(pinning, LIBBPF_PIN_BY_NAME);
} pebble_udp_targets SEC(".maps");

// EVOLVE-BLOCK-START
/*
 * Agent UDP selector
 *
 * Approach
 * --------
 * This selector intentionally does NOT special‑case GET vs SCAN or reserve
 * any workers for a particular verb. Instead, every incoming packet is
 * distributed in a simple, global round‑robin across all configured
 * SO_REUSEPORT workers.
 *
 * Motivation:
 *   - Under mixed GET/SCAN workloads, dedicating a subset of workers to
 *     SCANs leaves some cores under‑utilized when SCAN traffic is sparse,
 *     and causes localized queue build‑ups when SCANs surge.
 *   - By letting all N workers handle both short (GET) and long (SCAN)
 *     requests, we keep utilization more uniform and push the queueing
 *     knee closer to the true CPU limit.
 *   - We deliberately avoid per‑flow hashing so that occasional long SCANs
 *     are smeared across workers instead of all landing on one unlucky
 *     socket, which reduces tail latency at high load.
 *
 * Design:
 *   - The pebble_agent_state map stores:
 *
 *       struct agent_state {
 *           __u32 active;  // number of workers; written by Go once
 *           __u32 rr;      // global round‑robin counter; updated in BPF
 *       };
 *
 *     Go code already writes only the Active field; rr is naturally
 *     zero‑initialized on map update and then maintained entirely in BPF.
 *
 *   - For each packet:
 *       1) Read active. If zero, fall back to kernel selection (SK_PASS).
 *       2) Increment rr and compute slot = rr % active (or 0 if active==1).
 *       3) Call bpf_sk_select_reuseport exactly once with that slot.
 *
 * Properties:
 *   - Verb‑agnostic: does not inspect payloads at all.
 *   - Minimal state: one counter shared by all CPUs plus Active.
 *   - Straight‑line, verifier‑friendly logic (no loops, no complex parsing).
 *   - Cheap per packet: one map lookup, one 32‑bit increment, one 32‑bit
 *     division, and a single bpf_sk_select_reuseport() helper call.
 */

struct agent_state {
    __u32 active; /* number of configured workers (0..active-1) */
    __u32 rr;     /* global round-robin counter */
};

struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, struct agent_state);
    __uint(pinning, LIBBPF_PIN_BY_NAME);
} pebble_agent_state SEC(".maps");

SEC("sk_reuseport/selector")
enum sk_action agent_udp_selector(struct sk_reuseport_md *reuse)
{
    __u32 key = 0;
    struct agent_state *state = bpf_map_lookup_elem(&pebble_agent_state, &key);
    if (!state)
        return SK_PASS;

    __u32 active = state->active;
    if (active == 0)
        return SK_PASS;

    /* Clamp to the sockarray size for safety, though Go should enforce this. */
    if (active > 128)
        active = 128;

    /* Global round-robin across [0 .. active-1]. Exact atomicity is not
     * required; approximate fairness is sufficient under load. */
    __u32 rr = state->rr++;
    __u32 slot = 0;

    if (active > 1)
        slot = rr % active;
    else
        slot = 0;

    /* Extra safety: ensure slot is in range even if Active changed between
     * reading it and using it. */
    if (slot >= active)
        slot = slot % active;

    /* Exactly one selection attempt; additional calls would be ignored. */
    (void)bpf_sk_select_reuseport(reuse, &pebble_udp_targets, &slot, 0);

    return SK_PASS;
}
// EVOLVE-BLOCK-END

char _license[] SEC("license") = "GPL";

generation_feedback:
**How well this matches the intent**

- It’s very close to the *structural* design goals:
  - Uses only the existing `pebble_agent_state` map with exactly two fields (`active`, `rr`).
  - Logic is straight‑line, tiny, and makes exactly one `bpf_sk_select_reuseport` call.
  - Steering is verb‑agnostic: no payload inspection, just global RR across all workers.
- Behavior is consistent with the *utilization* intent:
  - At 80k, each of the 6 workers sees ~10.4k GET/s and 50–80 SCAN/s:
    - Workers 0–5 all report very similar `gets` and `scans`.
    - This confirms we no longer have GET‑only vs SCAN‑only workers; all 6 cores participate in both.
  - Per‑request busy‑waits stay at ~10µs/2ms for GET/SCAN, indicating the BPF path isn’t injecting noticeable overhead.
- The p99 curve still shows a classic CPU knee:
  - p99: 3.3ms @80k → 4.5ms @100k → 16.8ms @140k → ~600ms @160k.
  - That’s consistent with a CPU‑bound server starting to queue heavily near the ~140–145k mixed capacity; the selector is not obviously the bottleneck.

So: this attempt satisfies the simplicity + “let all N workers share GET/SCAN” objectives, and gives roughly balanced per‑worker load. It doesn’t introduce any mechanism to *further* shape tail latency near saturation (and probably can’t, given the constraints).

---

**Key behaviors / takeaways**

- **Load distribution**
  - All 6 workers see both verbs, with very tight spread in GET and SCAN counts → good fairness by request.
  - No worker appears significantly under‑ or over‑utilized in the provided logs.

- **Latency / throughput**
  - p99 grows smoothly until ~140k, then jumps at 160k as backlog accumulates.
  - This mirrors the earlier analysis: the knee is due to CPU saturation, not misrouting or imbalance.

- **Implementation details**
  - `state->rr++` mutates a shared map value from BPF on all CPUs. That’s allowed, but:
    - It’s non‑atomic, so increments can be lost under contention.
    - On some kernels, the verifier is stricter about non‑atomic writes to map values from multiple CPUs; using an explicit atomic op is safer.
  - `slot = rr % active;` followed by `if (slot >= active) slot = slot % active;` is redundant: the second modulo never fires.

---

**Concrete next changes to try**

1. **Make the RR counter update explicit and atomic**

   Rationale: Avoid any verifier quirks and lost increments; ensure fairness under high concurrency. This is cheap and keeps the design the same.

   ```c
   SEC("sk_reuseport/selector")
   enum sk_action agent_udp_selector(struct sk_reuseport_md *reuse)
   {
       __u32 key = 0;
       struct agent_state *state = bpf_map_lookup_elem(&pebble_agent_state, &key);
       if (!state)
           return SK_PASS;

       __u32 active = state->active;
       if (active == 0)
           return SK_PASS;
       if (active > 128)
           active = 128;

       /* Atomic fetch-and-increment of the global RR counter. */
       __u32 rr = __sync_fetch_and_add(&state->rr, 1);

       __u32 slot;
       if (active > 1)
           slot = rr % active;
       else
           slot = 0;

       (void)bpf_sk_select_reuseport(reuse, &pebble_udp_targets, &slot, 0);
       return SK_PASS;
   }
   ```

   - This replaces `state->rr++` with `__sync_fetch_and_add(&state->rr, 1)`, which compiles to a BPF_XADD and is verifier‑friendly in array maps.
   - Removes the redundant `if (slot >= active)` block.

2. **Optionally fold in CPU ID to reduce contention on a single sequence**

   Rationale: Still verb‑agnostic and simple, but slightly de‑correlates assignments from different CPUs when the atomic counter wraps or contends. Won’t change average behavior, but can smooth micro‑bursts.

   ```c
       /* ... after computing rr ... */
       __u32 cpu = bpf_get_smp_processor_id();
       __u32 slot;
       if (active > 1)
           slot = (rr + cpu) % active;
       else
           slot = 0;
   ```

   - Keeps one global `rr` (honoring the “Active + one counter” constraint) but effectively gives each CPU its own phase in the round‑robin.
   - Still a single helper call, no new maps.

3. **Validation step (no code change): confirm balance at 140k/160k**

   - After the above tweak, re‑run at 140k and 160k and:
     - Check that per‑worker `gets` and `scans` remain tightly clustered.
     - Compare aggregate completions vs offered load to see if we’re any closer to the theoretical ~145k/s.
   - If the knee and p99 look essentially unchanged (likely), that’s a strong indication we’ve reached the practical limit of what steering alone can do under the given constraints.

